import json,re
P='partK.json'
d=json.load(open(P)); M={x["file"]:x for x in d}
H='<h2>מה לעשות עכשיו</h2>'
def ins(f,before,txt):
    b=M[f]["body"]; assert before in b,(f,before); M[f]["body"]=b.replace(before,txt+before,1)
ins("lost-package-what-to-do.html",H,'<p>אם החבילה נשלחה אליכם מחנות מקוונת, פנו גם אל החנות. לעתים היא יכולה לשלוח חבילה חדשה או להחזיר כסף, ואז נפתרת הבעיה בלי להמתין לסיום החקירה. שמרו על שיחה מסודרת עם כל הצדדים כדי לא לאבד זמן.</p>\n<p>ככלל, כל עיכוב מקבלים יפה יותר כשהפרטים מסודרים: מספר מעקב, תאריכים ופרטי הכתובת.</p>\n')
ins("ship-documents-abroad.html",H,'<p>שימו לב גם לתאריכים. הזמן להגעה של מעטפה משתנה לפי יעד, שיטה וחברה, ואין מספר אחד שנכון לכולם. לכן שואלים את חברת השילוח מה זמן המסירה המשוער, ומוסיפים לו מרווח לפני המועד שבו המסמך נחוץ.</p>\n')
ins("damage-claims-fragile-items.html",H,'<p>חשוב גם לשמור על קשר עם המקבל. אם המקבל הוא אדם אחר, בקשו ממנו לצלם מיד ולא להשליך כלום. כך אין צורך להסתמך על תיאור בעל פה בהמשך. ככל שהתיעוד מסודר יותר, התביעה פשוטה יותר.</p>\n')
ins("low-cost-international-shipping.html",H,'<p>לסיכום, אין קסם. כל הצעה זולה יוצאת מאיזון בין מחיר, מהירות ושירות. כשמבינים מה חשוב לכם, קל יותר לבחור נכון, ולא לשלם על מה שלא צריך.</p>\n<p>אפשר גם לבדוק אם הפריט שווה שילוח מלא, או שכדאי לקנות אותו מקומית. לפעמים זה החיסכון הגדול ביותר.</p>\n')
ins("consolidated-shipping.html",H,'<p>כשהכל מוכן, בקשו הצעה מפורשת על משלוח מאוחד. השוו אותה לסכום של כל המשלוחים הנפרדים, ובדקו גם את הזמן הנוסף. אם ההפרש קטן והזמן חשוב, שליחה נפרדת יכולה להיות הבחירה הנכונה. הצוות שלנו יכול לעזור לבדוק את שתי האפשרויות.</p>\n<p>כדאי לדעת שהאיחוד עובד טוב במיוחד כשמתכננים מראש, ולא כשמתחילים לחשוב עליו ברגע האחרון.</p>\n')
ins("consolidated-shipping.html",'<h2>איך מתכוננים','<p>איחוד שימושי גם לעסקים: יבואן קטן שמקבל סחורה מכמה ספקים יכול לרכז אותה במחסן אחד ולשלוח כמשלוח אחד לישראל. זה מצמצם את מספר הדיווחים למכס, אבל מחייב סדר במסמכים של כל ספק.</p>\n')
for it in d:
    t=re.sub(r'<[^>]+>',' ',it["body"]); print(it["file"],len(t.split()))
json.dump(d,open(P,'w'),ensure_ascii=False,indent=1)
